"use client";

import React, { useState } from "react";
import { Users } from "lucide-react";

export function ProductBundleDiscountMeter() {
  const [itemsCount, setItemsCount] = useState(2);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <Users className="w-4 h-4 text-violet-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Volume discount</span>
        </div>
        <button 
          onClick={() => setItemsCount(Math.min(5, itemsCount + 1))}
          className="p-1 rounded bg-secondary hover:bg-secondary/60 text-xs font-bold"
        >
          Add Item
        </button>
      </div>

      <div className="space-y-4">
        <div>
          <div className="flex justify-between text-xs mb-1.5">
            <span className="text-muted-foreground/60">{itemsCount} items in bundle</span>
            <span className="font-bold text-violet-400">-{itemsCount * 5}% off</span>
          </div>
          <div className="h-2 bg-secondary/40 rounded-full overflow-hidden">
            <div className="h-full bg-violet-500" style={{ width: `${(itemsCount / 5) * 100}%` }} />
          </div>
        </div>
      </div>
    </div>
  );
}
